// === Tab: mySketch ===
/*
Genuary 2025 day 8 prompt: Draw one million of something.
January 8, 2025
Segmented Metameric Lacunarity
by Metamere
https://genart.social/@Metamere
on Mastodon, #Genuary2025 #Genuary8 #Genuary
*/

const name_str = 'GEN25-8, seed no. '
const palette = ["#cc3919", "#e0741a", "#f3b930", "#86b254", "#4b7b27", "#418564", "#3641d3", "#8c28a5"] // Metamere's custom palette
const pg = [] // graphics buffers array
let iOSiPadOS // check for ios to avoid fullscreen errors

// control parameters
let num = 100 // number of cubes per side. total = num ^ 3
let portions = 16 // don't exceed num. Nice when dealing with powers of two for even divisions.
// num = 64 or 32 with portions = 32 or 16 are satisfying.
const portion_offsets = []


function setup(init=true,randomize = true) {
  is_setting_up = true
  S = min(W=windowWidth,H=windowHeight)
  if(S < 450) num = 64 // Can't really notice the difference on a phone, and it will draw faster
  mobile = (S < 1000) 

  w = W/2
  h = H/2
  s = S/2
  margin = S/20
  touch_margin = 0.1

  frameRate(20)

  if(init){
    createCanvas(W, H)
    iOSiPadOS = (/^iP/.test(navigator.platform) || /^Mac/.test(navigator.platform) && navigator.maxTouchPoints > 4)
    pg_temp = createGraphics(W,H, WEBGL) 
    // By using only one WEBGL buffer, we can use many more total buffers. 
    // Chrome seemed to be limited to 15 WEBGL buffers.
    pg_temp.angleMode(DEGREES)
    pg_temp.noStroke()
    for(let i = 0; i <= portions; i++){ pg[i] = createGraphics(W, H) }
  }
  else{
    resizeCanvas(W, H)
    pg_temp.resizeCanvas(W, H)
    for(let i = 0; i <= portions; i++){ pg[i].resizeCanvas(W, H) }
  }
  if(randomize) seed = ~~random(87654321)
  noiseSeed(seed)
  randomSeed(seed)

  let TS
  if(mobile){
    let AR = W / H
    if(AR > 0.8) TS = margin / 2
    else TS = margin
  } 
  else TS = margin / 3
  textSize(TS)

  opacity = 15 + map(num, 1, 100, 40, 0)
  palette_offset = ~~random(100)
  total = pow(num, 3)
  s2 = s * 0.6
  x = y = z = 0
  x_pos = y_pos = z_pos = -s2
  s_inc = s2 * 2 / num
  box_size = s_inc* 0.93

  rotation_angle = random([45,60])

  // I am not as big of a fan of the appearance with the stroke on, but I'll leave it here for others to try
  // stroke_on = random() < 0.2 
  // if(stroke_on){
  //   stroke_shade = random() < 0.75 ? 0 : 255 
  //   pg_temp.strokeWeight(box_size * 0.05)
  //   pg_temp.stroke(stroke_shade, 90)
  // } else{ pg_temp.noStroke() }

  for(let i = 0; i < portions; i++){ portion_offsets[i] = 0 }
  pg_temp.clear()
  buffer_index = 0

  end_loop = false
  mX = 0
  mY = 0
  t = 0
  animated = true
  final = false
  is_setting_up = false
  loop()
  describe('A cube made up of 100 by 100 by 100 cubes, all partially transparent and colored by a 3D noise field. The 100 layers are added on one at a time, and can be separated in various ways with interactive controls.')
}

function randomCol() {
  let col = color(palette[~~random(palette.length)])
  col.setAlpha(opacity)
  fill(col)
}

let sub_portions = portions
let is_setting_up = false

function draw() {
  if(!animated || is_setting_up) return
  if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
    mX = constrain(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/W, touch_margin, 1 - touch_margin, 0, 1), 0, 1)
    if(mX < 0.03 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < W * touch_margin) mX = 0
    mY = constrain(map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/H, touch_margin, 1 - touch_margin, 0, 1), 0, 1)
  }

	if(!end_loop){

    pg_temp.push()
    pg_temp.ortho()
    pg_temp.rotateX(-35)
    pg_temp.rotateY(rotation_angle)
    pg_temp.translate(s_inc, s_inc)
    for(let i = 0; i < num * num; i++){
      pg_temp.push()
      let col_index = ~~((2 * noise(x / num,y / num, z / num) * palette.length + palette_offset) % palette.length)
      var col = color(palette[col_index])
      col.setAlpha(opacity)
      pg_temp.fill(col)
      pg_temp.translate(x_pos, y_pos, z_pos)
      // pg_temp.rotateY(z/num * 90)
      pg_temp.box(box_size)

      x++
      if(x == num){
        x = 0
        y++
        if(y == num){
          y = 0
          z++
          if(z == num){
            final = true
            frameRate(60)
            signature()
          } 
          z_pos = map(z, 0, num, -s2, s2)
        }
        y_pos = map(y, 0, num, -s2, s2)
      }
      pg_temp.pop()
      x_pos = map(x, 0, num, -s2, s2)
    }
    pg_temp.pop()

    pg[buffer_index].image(pg_temp, 0, 0)
    pg_temp.clear()
    buffer_index_temp = min(portions-1, int(z / (num - 1) * portions))
    if(buffer_index_temp > buffer_index){
      buffer_index = buffer_index_temp
    }
  }

  if(!end_loop || (end_loop && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)))){
    background(0)
    sub_portions = pow(2, round((Math.log2(portions) - 1) * mY))
    for(let i = 0; i < portions; i++){
      const x_offset = map(int(i / sub_portions), 0, portions/sub_portions - 1, -1, 1) * mX * W / sub_portions
      portion_offsets[i] = lerp(portion_offsets[i], x_offset, 0.08)
      image(pg[i], portion_offsets[i], 0)
    }
    if(final) signature()
  }
  if(final) end_loop = true
}

function signature(){
  push()
  noStroke()
  fill(200)
  textAlign(LEFT, TOP)
  const y_pos1 = mobile ? margin * 0.5 : H - margin * 0.5
  const y_pos2 = mobile ? H - margin * 0.25 : y_pos1
  text(name_str + seed, margin/2, y_pos1)
  textAlign(RIGHT, mobile ? BOTTOM : TOP)
  text('Metamere', W - margin/2, y_pos2)
  pop()
}

function keyPressed(){
  const key_L = key.toLowerCase()
	if(key_L === 'f'){
		if(fullscreen()) fullscreen(false)
		else fullscreen(true)
	}
  else if(key_L === 's') save_img()
  else if(key_L === 'r') setup(false, true)
  else if(key === ' ') animated = !animated
}

function save_img(){
  const span = round(abs(portion_offsets[0]) * 2 / W, 2)
  sub_p = span < 0.01 ? '' : ', ' + int(portions / sub_portions) + '-' + span
  console.log(span)
  let save_name = `${name_str} ${seed}${num != 100 ? '-' + num : ''}, ${W}x${H}${sub_p}, by Metamere`
  saveCanvas(save_name, "jpg")
}

let touch_mode, resize_timeout

function touchStarted(){ touch_mode = touches.length }
function touchEnded(){
	if(touch_mode == 1 && !iOSiPadOS){
		go_fullscreen()
	}
  else if (touch_mode == 3){
    setup(false, true)
  }
  touch_mode = 0
	return false
}

function go_fullscreen() {
	if (fullscreen()) return
	fullscreen(true)
}

function windowResized(){
  clearTimeout(resize_timeout)
	resize_timeout = setTimeout(() => {
    if(!((windowWidth === H && windowHeight === W) || (windowWidth === W && windowHeight === H))){
      setup(false, false) 
    }
  }, 150)
}
